<section><div class="contact-toolbar"><div><p class="eyebrow">CONTABILIDAD · <?= $page['type']==='customer'?'CLIENTES':'PROVEEDORES' ?></p><h1>Pagos</h1><p class="section-subtitle"><?= $page['total'] ?> registros</p></div><a class="contact-button contact-button-primary" href="pagos.php?type=<?= $page['type'] ?>&amp;new=1">Nuevo pago</a></div>
<form class="contact-filters"><input type="hidden" name="type" value="<?= $page['type'] ?>"><label>Buscar<input type="search" name="q" value="<?= accountingEscape($page['search']) ?>"></label><label>Estado<select name="status" data-auto-submit><option value="all">Todos</option><?php foreach(paymentStatuses() as $key=>$label): ?><option value="<?= $key ?>" <?= $page['statusFilter']===$key?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label><input type="checkbox" name="available" value="1" <?= $page['availableFilter']?'checked':'' ?>> Con importe disponible</label><button class="contact-button">Buscar</button></form>
<div class="contact-table-wrap"><table class="contact-table"><thead><tr><th>Referencia</th><th>Contacto</th><th>Tipo</th><th>Fecha</th><th>Caja / banco</th><th>Importe</th><th>Sin aplicar</th><th>Estado</th></tr></thead><tbody><?php foreach($page['rows'] as $row): ?><tr><td><a class="contact-name" href="pagos.php?type=<?= $page['type'] ?>&amp;id=<?= (int)$row['id'] ?>"><?= accountingEscape($row['name']) ?></a></td><td><?= accountingEscape($row['contact_name']) ?></td><td><?= $row['direction']==='inbound'?'Recibir':'Enviar' ?></td><td><?= accountingEscape($row['payment_date']) ?></td><td><?= accountingEscape($row['account_name']) ?></td><td><?= accountingEscape($row['amount'].' '.$row['currency_code']) ?></td><td><?= $row['status']==='cancel'?'0.00':accountingEscape($row['available']) ?></td><td><?= paymentStatuses()[$row['status']] ?></td></tr><?php endforeach; ?><?php if(!$page['rows']): ?><tr><td colspan="8">No hay pagos que coincidan con los filtros.</td></tr><?php endif; ?></tbody></table></div>
<nav class="contact-pagination"><span>Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach(['Anterior'=>$page['currentPage']-1,'Siguiente'=>$page['currentPage']+1] as $label=>$number): ?><?php if($number>=1&&$number<=$page['pages']): ?><a class="contact-button" href="pagos.php?<?= accountingEscape(http_build_query(['type'=>$page['type'],'q'=>$page['search'],'status'=>$page['statusFilter'],'available'=>$page['availableFilter']?'1':null,'page'=>$number])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav></section>
